  BabyRecipe(id: 'b19v00', title: 'Meyveli yoğurt kasesi', age: '12+', category: 'Yoğurt', ingredient: 'yoğurt', vegetable: 'muz', ingredients: ['4 yemek kaşığı tam yağlı sade yoğurt', '3 yemek kaşığı ezilmiş veya küçük doğranmış meyve (seçtiğiniz)', '1 yemek kaşığı ince yulaf ezmesi', '1 tutam tarçın (isteğe bağlı)'], steps: ['Meyveyi yıkayın; muz ve armudu çatalla ezin, çileği ve şeftaliyi küçük parçalara bölün.', 'Yaban mersinlerini ikiye veya dörde bölün.', 'Yoğurdu kaseye alın, meyveyi ve yulafı ekleyin.', 'Tarçın serpip hemen servis edin.'], variants: ['muz', 'çilek', 'armut', 'şeftali', 'yaban mersini'], tips: ['Yuvarlak küçük meyveleri (yaban mersini, üzüm) daima bölerek verin.', 'Bal eklemeyin; 12 aydan sonra bile şekersiz alışkanlık önerilir.'], storage: 'Hemen tüketin.'),
  BabyRecipe(id: 'b20v00', title: 'Patatesli sebze ezmesi', age: '8+', category: 'Sebze', ingredient: 'patates', vegetable: 'brokoli', ingredients: ['1 orta boy patates', 'Yarım su bardağı sebze (seçtiğiniz)', '1 çay kaşığı tereyağı', '2 yemek kaşığı süt veya anne sütü/mama'], steps: ['Patatesi soyup küp küp doğrayın, 10 dakika haşlayın.', 'Sebzeyi ekleyip 8 dakika daha, ikisi de yumuşayana kadar pişirin.', 'Süzün, tereyağı ve sütle birlikte çatalla ezin.', 'Yaşa göre hafif taneli ya da pürüzsüz bırakıp ılık verin.'], variants: ['brokoli', 'karnabahar', 'havuç', 'bezelye', 'ıspanak'], tips: ['12 aydan önce inek sütünü içecek olarak vermeyin; yemeklerde az miktarda kullanılabilir.'], storage: 'Buzdolabında 24 saat.'),
  BabyRecipe(id: 'b21v00', title: 'Sebzeli irmik lapası', age: '9+', category: 'Tahıl', ingredient: 'irmik', vegetable: 'havuç', ingredients: ['1 yemek kaşığı irmik', '2 yemek kaşığı rendelenmiş sebze (seçtiğiniz)', '1 su bardağı içme suyu', '1 çay kaşığı tereyağı'], steps: ['Sebzeyi suyla 7–8 dakika yumuşayana kadar pişirin.', 'İrmiği yağmur gibi serperek ve sürekli karıştırarak ekleyin.', 'Topaklanmaması için karıştırmaya devam ederek 4–5 dakika koyulaşana kadar pişirin.', 'Tereyağını ekleyip ılıtın.'], variants: ['havuç', 'kabak', 'balkabağı'], tips: ['İrmik buğdaydan yapılır, gluten içerir.'], storage: 'Hemen tüketin; bekleyince sertleşir.'),
  BabyRecipe(id: 'b22v00', title: 'Sebzeli kuskus', age: '12+', category: 'Tahıl', ingredient: 'kuskus', vegetable: 'kabak', ingredients: ['3 yemek kaşığı kuskus', 'Yarım su bardağı ince doğranmış sebze (seçtiğiniz)', 'Yarım su bardağı sıcak su', '1 tatlı kaşığı zeytinyağı'], steps: ['Zeytinyağında sebzeyi 5–6 dakika yumuşayana kadar soteleyin.', 'Kuskusu ekleyip 1 dakika çevirin.', 'Sıcak suyu ilave edin, kapağı kapatıp ocağı kapatın.', '10 dakika demlendirin, çatalla taneleri ayırın ve ılık servis edin.'], variants: ['kabak', 'havuç', 'bezelye', 'kırmızı biber'], tips: ['Kuskus buğday içerir.'], storage: 'Buzdolabında 24 saat.'),
  BabyRecipe(id: 'b23v00', title: 'Sebzeli kinoa', age: '10+', category: 'Tahıl', ingredient: 'kinoa', vegetable: 'kabak', ingredients: ['2 yemek kaşığı kinoa', 'Yarım su bardağı ince doğranmış sebze (seçtiğiniz)', '1 su bardağı içme suyu', '1 çay kaşığı zeytinyağı'], steps: ['Kinoayı acılığını gidermek için ince süzgeçte bol suyla ovarak yıkayın.', 'Kinoa ve suyu tencereye alın, kaynayınca kısık ateşte 10 dakika pişirin.', 'Sebzeyi ekleyip 8–10 dakika daha, su çekilip taneler yumuşayana kadar pişirin.', 'Zeytinyağını ekleyin, yaşa göre ezin.'], variants: ['kabak', 'havuç', 'brokoli', 'balkabağı'], tips: ['Kinoa glutensizdir; çeşitlendirme için iyi bir tahıl alternatifidir.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'b24v00', title: 'Tavuklu sebze çorbası', age: '9+', category: 'Çorba', ingredient: 'tavuk', vegetable: 'havuç', ingredients: ['50 g tavuk göğsü veya but', '1 küçük patates', 'Yarım su bardağı doğranmış sebze (seçtiğiniz)', '1 tatlı kaşığı pirinç veya arpa şehriye', '2 su bardağı içme suyu'], steps: ['Tavuğu suyla haşlayın; kaynayınca köpüğünü alın ve 20 dakika pişirin.', 'Tavuğu çıkarıp ince ince didikleyin.', 'Suya patates, sebze ve pirinci ekleyip 20 dakika pişirin.', 'Tavuğu geri ekleyin; yaşa göre blenderdan geçirin veya parçalı bırakın.', 'Ilıtarak servis edin.'], variants: ['havuç', 'kabak', 'patates', 'kereviz', 'balkabağı'], tips: ['Çorbayı bebeğe vermeden önce bileğinizin iç kısmında sıcaklığını kontrol edin.'], storage: 'Buzdolabında 24 saat; 1 ay dondurulabilir.'),
  BabyRecipe(id: 'b25v00', title: 'Kırmızı mercimek çorbası', age: '8+', category: 'Çorba', ingredient: 'kırmızı mercimek', vegetable: 'havuç', ingredients: ['3 yemek kaşığı kırmızı mercimek', '1 küçük sebze (seçtiğiniz)', '1 yemek kaşığı ince kıyılmış soğan', '2 su bardağı içme suyu', '1 çay kaşığı tereyağı'], steps: ['Mercimeği yıkayıp süzün; sebzeyi küçük doğrayın.', 'Tereyağında soğanı 2 dakika yumuşatın.', 'Mercimek, sebze ve suyu ekleyip kaynayınca kısık ateşte 25 dakika pişirin.', 'Blenderdan geçirip kıvamını kaynamış suyla ayarlayın.', 'Ilık servis edin.'], variants: ['havuç', 'kabak', 'balkabağı', 'patates'], tips: ['Bir yaşından büyük çocuklarda servis ederken birkaç damla limon ekleyebilirsiniz.'], storage: 'Buzdolabında 48 saat; dondurulabilir.'),
  BabyRecipe(id: 'b26v00', title: 'Sebzeli yumurta muffin', age: '12+', category: 'Fırın', ingredient: 'yumurta', vegetable: 'ıspanak', ingredients: ['2 yumurta', '3 yemek kaşığı çok ince doğranmış sebze (seçtiğiniz)', '2 yemek kaşığı lor peyniri', '1 yemek kaşığı süt'], steps: ['Fırını 180 °C\'ye ısıtın; 6\'lı mini muffin kalıbını yağlayın.', 'Yumurtaları sütle çırpın; sebze ve loru ekleyin.', 'Karışımı kalıplara üçte iki oranında doldurun.', '15–18 dakika, kürdan batırınca temiz çıkana kadar pişirin.', 'Kalıpta 5 dakika bekletip çıkarın, ılık verin.'], variants: ['ıspanak', 'kabak', 'kırmızı biber', 'brokoli'], tips: ['Parmak yiyecek olarak bebeğin kendi kendine yemesini destekler.'], storage: 'Buzdolabında 48 saat; dondurulabilir.'),
  BabyRecipe(id: 'b27v00', title: 'Sebzeli erişte', age: '12+', category: 'Makarna', ingredient: 'erişte', vegetable: 'havuç', ingredients: ['Yarım su bardağı ev yapımı veya hazır erişte', 'Yarım su bardağı ince doğranmış sebze (seçtiğiniz)', '1 tatlı kaşığı tereyağı', '1 yemek kaşığı süzme yoğurt'], steps: ['Erişteyi tuzsuz suda 10–12 dakika yumuşayana kadar haşlayın.', 'Sebzeyi tereyağında kapağı kapalı 6–7 dakika pişirin.', 'Süzülmüş erişteyi sebzeyle karıştırın.', 'Ilıyınca yoğurtla servis edin; uzun erişteleri küçük parçalara kesin.'], variants: ['havuç', 'kabak', 'brokoli', 'bezelye'], tips: ['Uzun makarnaları kesmek boğulma riskini azaltır.'], storage: 'Buzdolabında 24 saat.'),
  BabyRecipe(id: 'b28v00', title: 'Fırında sebzeli tavuk köftesi', age: '12+', category: 'Et', ingredient: 'tavuk kıyma', vegetable: 'havuç', ingredients: ['100 g tavuk kıyması', '3 yemek kaşığı ince rendelenmiş sebze (seçtiğiniz), suyu sıkılmış', '2 yemek kaşığı yulaf ezmesi', '1 tatlı kaşığı zeytinyağı', '1 tutam kimyon'], steps: ['Fırını 190 °C\'ye ısıtın.', 'Tüm malzemeyi yoğurup 10 dakika buzdolabında dinlendirin.', 'Islak elle küçük yassı köfteler şekillendirip kâğıt serili tepsiye dizin.', '18–20 dakika, içi tamamen beyazlayana kadar pişirin.', 'Ilıtıp bebeğin tutabileceği büyüklükte servis edin.'], variants: ['havuç', 'kabak', 'brokoli'], tips: ['Tavuk kıymasının içi mutlaka iyice pişmelidir.'], storage: 'Buzdolabında 48 saat; 1 ay dondurulabilir.'),
  BabyRecipe(id: 'b29v00', title: 'Yulaflı sebze köftesi', age: '12+', category: 'Fırın', ingredient: 'yulaf', vegetable: 'havuç', ingredients: ['4 yemek kaşığı yulaf ezmesi', '3 yemek kaşığı rendelenmiş sebze (seçtiğiniz)', '2 yemek kaşığı ezilmiş haşlanmış nohut', '1 yumurta', '1 yemek kaşığı ince kıyılmış maydanoz'], steps: ['Fırını 190 °C\'ye ısıtın.', 'Sebzenin suyunu sıkın, tüm malzemeyle karıştırıp 10 dakika bekletin.', 'Ceviz büyüklüğünde yassı köfteler yapın.', 'Kâğıt serili tepside 20 dakika, iki yüzü hafif kızarana kadar pişirin (10. dakikada çevirin).', 'Ilıtıp servis edin.'], variants: ['havuç', 'kabak', 'tatlı patates'], tips: ['Etsiz günler için iyi bir protein ve lif kaynağıdır.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'ozgun001', title: 'Avokado ve muz ezmesi', age: '6+', category: 'Meyve', ingredient: 'avokado', vegetable: 'muz', ingredients: ['2 yemek kaşığı olgun avokado', '2 yemek kaşığı olgun muz'], steps: ['Meyveleri yıkayıp soyun.', 'Çatalla tamamen ezin.', 'Hazırladıktan hemen sonra yaşa uygun kıvamda sunun.']),
  BabyRecipe(id: 'ozgun002', title: 'Armut püresi', age: '6+', category: 'Meyve', ingredient: 'armut', vegetable: 'armut', ingredients: ['1 küçük olgun armut', 'Gerekirse az miktarda içme suyu'], steps: ['Armutu yıkayıp soyun, çekirdeklerini çıkarın.', 'Sertse az suyla yumuşayana kadar pişirin.', 'Ezip ılıtarak sunun.']),
  BabyRecipe(id: 'ozgun003', title: 'Elmalı yulaf lapası', age: '6+', category: 'Tahıl', ingredient: 'yulaf', vegetable: 'elma', ingredients: ['2 yemek kaşığı ince yulaf', 'Yarım elma', 'İçme suyu'], steps: ['Elmayı soyup çekirdeğini çıkarın ve rendeleyin.', 'Yulaf ve suyla iyice yumuşayana kadar pişirin.', 'Ilıtarak uygun kıvamda sunun.']),
  BabyRecipe(id: 'ozgun006', title: 'İyi pişmiş yumurtalı avokado ezmesi', age: '6+', category: 'Yumurta', ingredient: 'yumurta', vegetable: 'avokado', ingredients: ['1 adet tamamen pişmiş yumurta', '2 yemek kaşığı olgun avokado'], steps: ['Yumurtayı sarısı ve beyazı tamamen katılaşana kadar pişirin.', 'Avokadoyla birlikte iyice ezin.', 'Uygun kıvamda sunun; yumurta alerjenini dikkate alın.']),
  BabyRecipe(id: 'ozgun013', title: 'Mercimekli sebze köftesi', age: '9+', category: 'Baklagil', ingredient: 'mercimek', vegetable: 'havuç', ingredients: ['3 yemek kaşığı iyi pişmiş kırmızı mercimek', '2 yemek kaşığı pişmiş havuç', '1 yemek kaşığı ince yulaf'], steps: ['Tüm malzemeleri iyice ezin.', 'Yumuşak küçük köfteler oluşturun.', 'Fırında içi tamamen pişene kadar pişirin, uygun şekilde parçalayın.']),
  BabyRecipe(id: 'ozgun014', title: 'Yoğurtlu yulaf ve şeftali', age: '9+', category: 'Yoğurt', ingredient: 'yoğurt', vegetable: 'şeftali', ingredients: ['2 yemek kaşığı sade pastörize yoğurt', '2 yemek kaşığı pişmiş yulaf', 'Yarım olgun şeftali'], steps: ['Yulafı suyla tamamen pişirip soğutun.', 'Şeftaliyi soyup çok iyi ezin.', 'Yoğurtla karıştırıp hemen sunun.']),
  BabyRecipe(id: 'ozgun020', title: 'Elmalı tarçınlı yumuşak pankek', age: '12+', category: 'Kahvaltı', ingredient: 'yulaf', vegetable: 'elma', ingredients: ['1 yumurta', '3 yemek kaşığı ince yulaf', 'Yarım rendelenmiş elma', 'İsteğe bağlı çok az tarçın'], steps: ['Malzemeleri pürüzsüzce karıştırın.', 'Yapışmaz tavada küçük pankeklerin iki yüzünü de tamamen pişirin.', 'Yumuşak ve yaşa uygun parçalara bölerek sunun.']),
  BabyRecipe(id: 'ab18_01', title: 'Mini sebzeli pizza', age: '18+', category: 'Fırın', ingredient: 'lavaş', vegetable: 'mantar', ingredients: ['1 küçük tam buğday lavaş', '2 yemek kaşığı rendelenmiş domates', '2 yemek kaşığı rendelenmiş az tuzlu kaşar', '2 yemek kaşığı ince doğranmış kırmızı biber ve mantar', '1 tutam kekik'], steps: ['Fırını 200 °C\'ye ısıtın.', 'Lavaştan bardak ağzıyla 4–5 yuvarlak kesin.', 'Üzerlerine domates sürün, sebzeleri ve kaşarı paylaştırın, kekik serpin.', '8–10 dakika, peynir eriyip kenarlar kızarana kadar pişirin.', 'Ilıtıp dilimleyerek verin.'], tips: ['Hazır pizza sosu yerine taze domates kullanmak tuz ve şekeri azaltır.'], storage: 'Aynı gün tüketin.'),
  BabyRecipe(id: 'ab18_02', title: 'Etli taze fasulye', age: '18+', category: 'Et', ingredient: 'dana kuşbaşı', vegetable: 'taze fasulye', ingredients: ['60 g küçük doğranmış dana eti', '1 su bardağı doğranmış taze fasulye', '1 küçük domates, rendelenmiş', '1 yemek kaşığı ince doğranmış soğan', '1 su bardağı sıcak su', '1 tatlı kaşığı zeytinyağı'], steps: ['Zeytinyağında eti kapağı kapalı olarak kendi suyunu çekene kadar 10 dakika pişirin.', 'Soğanı ekleyip 2 dakika, ardından domatesi ekleyip 2 dakika çevirin.', 'Fasulyeyi ve sıcak suyu ekleyin; kısık ateşte 35–40 dakika et ve fasulye yumuşayana kadar pişirin.', 'Eti küçük lifler hâlinde ayırın, fasulyeleri 1 cm boyunda kesin.'], tips: ['Eti düdüklü tencerede pişirmek süreyi kısaltır ve daha yumuşak yapar.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'ab18_03', title: 'Fırında somon ve patates', age: '18+', category: 'Balık', ingredient: 'somon', vegetable: 'patates', ingredients: ['70 g kılçıksız somon fileto', '1 küçük patates, ince dilimlenmiş', '1 tatlı kaşığı zeytinyağı', 'Birkaç dal dereotu', 'Birkaç damla limon suyu'], steps: ['Fırını 190 °C\'ye ısıtın.', 'Patates dilimlerini zeytinyağıyla harmanlayıp tepsiye dizin, 15 dakika pişirin.', 'Somonu patateslerin yanına yerleştirip dereotu ve limon ekleyin.', '12–15 dakika daha, balık opaklaşıp kolayca dağılana kadar pişirin.', 'Kılçık kontrolü yapıp küçük parçalara ayırın.'], tips: ['Haftada 1–2 kez balık önerilir.'], storage: 'Aynı gün tüketin.'),
  BabyRecipe(id: 'ab18_04', title: 'Ispanaklı lorlu börek parmakları', age: '18+', category: 'Fırın', ingredient: 'yufka', vegetable: 'ıspanak', ingredients: ['1 adet yufka', '1 su bardağı ince kıyılmış ıspanak', '3 yemek kaşığı lor peyniri', '1 yumurta', '3 yemek kaşığı süt', '1 tatlı kaşığı zeytinyağı'], steps: ['Fırını 180 °C\'ye ısıtın.', 'Ispanağı zeytinyağında 3 dakika soldurup soğutun, lorla karıştırın.', 'Yumurta ve sütü çırpın; yufkayı 4 üçgene kesip her birine bu karışımdan sürün.', 'Geniş kenarına iç harcı koyup parmak şeklinde sarın, üstlerine kalan karışımdan sürün.', '20–25 dakika, üzerleri kızarana kadar pişirin; ılıtıp verin.'], tips: ['Lor peyniri tuzu düşük bir seçenektir.'], storage: 'Buzdolabında 48 saat; dondurulabilir.'),
  BabyRecipe(id: 'ab18_05', title: 'Mercimekli bulgur köftesi (yumuşak)', age: '18+', category: 'Baklagil', ingredient: 'kırmızı mercimek', vegetable: 'domates', ingredients: ['3 yemek kaşığı kırmızı mercimek', '2 yemek kaşığı ince bulgur', '1 su bardağı su', '1 tatlı kaşığı domates salçası (az tuzlu)', '1 yemek kaşığı ince kıyılmış taze soğan', '1 yemek kaşığı zeytinyağı', 'Birkaç dal maydanoz'], steps: ['Mercimeği suyla 15 dakika, dağılana kadar pişirin.', 'Ocaktan alıp bulguru ekleyin, kapağı kapalı 20 dakika şişmeye bırakın.', 'Zeytinyağında taze soğan ve salçayı 2 dakika çevirip karışıma ekleyin.', 'Maydanozu ekleyip yoğurun, küçük yumuşak köfteler şekillendirin.', 'Marul yaprağında veya tabakta servis edin.'], tips: ['Acı biber ve isot kullanmayın.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'ab18_06', title: 'Yoğurtlu tavuk ve sebze sote', age: '18+', category: 'Et', ingredient: 'tavuk', vegetable: 'kabak', ingredients: ['80 g tavuk göğsü, küçük küp', 'Yarım kabak ve yarım havuç, küçük doğranmış', '1 tatlı kaşığı zeytinyağı', '2 yemek kaşığı yoğurt', '1 tutam kekik'], steps: ['Zeytinyağında tavuğu 6–7 dakika her yüzü beyazlayana kadar pişirin.', 'Sebzeleri ekleyip kapağı kapalı 10 dakika yumuşatın; gerekirse 2 kaşık su ekleyin.', 'Tavuğun içi tamamen pişince ocaktan alın.', 'Ilıyınca yoğurt ve kekikle servis edin.'], tips: ['Yoğurdu sıcak yemeğe eklemeyin, kesilir.'], storage: 'Yoğurtsuz hâli buzdolabında 24 saat.'),
  BabyRecipe(id: 'ab18_07', title: 'Muzlu yulaf pankek', age: '18+', category: 'Kahvaltı', ingredient: 'yulaf', vegetable: 'muz', ingredients: ['1 olgun muz', '1 yumurta', '4 yemek kaşığı ince yulaf ezmesi', '1 tutam tarçın', '1 çay kaşığı tereyağı'], steps: ['Muzu çatalla iyice ezin; yumurta, yulaf ve tarçınla karıştırın.', 'Karışımı 5 dakika dinlendirin.', 'Yapışmaz tavayı tereyağıyla hafifçe yağlayıp yemek kaşığıyla küçük yuvarlaklar dökün.', 'Kısık ateşte her yüzünü 2 dakika, ortası pişene kadar pişirin.', 'Ilıtıp servis edin.'], tips: ['Muzun tatlılığı yeterlidir; şeker veya bal eklemeyin.'], storage: 'Buzdolabında 24 saat; dondurulabilir.'),
  BabyRecipe(id: 'ab18_08', title: 'Sebzeli tavuk pilavı', age: '18+', category: 'Tahıl', ingredient: 'pirinç', vegetable: 'bezelye', ingredients: ['3 yemek kaşığı pirinç', '50 g haşlanmış ve didiklenmiş tavuk', '2 yemek kaşığı bezelye', '2 yemek kaşığı küçük doğranmış havuç', '1 su bardağı tavuk haşlama suyu', '1 tatlı kaşığı tereyağı'], steps: ['Pirinci 20 dakika ılık suda bekletip süzün.', 'Tereyağında havuç ve bezelyeyi 3 dakika çevirin.', 'Pirinci ekleyip 1 dakika kavurun; sıcak haşlama suyunu ilave edin.', 'Kısık ateşte 15 dakika suyunu çekene kadar pişirin, tavuğu ekleyip 10 dakika demlendirin.'], tips: ['Bezelyeleri hafifçe ezerek boğulma riskini azaltın.'], storage: 'Hızla soğutup buzdolabında 24 saat.'),
  BabyRecipe(id: 'ab18_09', title: 'Fırında sebzeli patates kroket', age: '18+', category: 'Fırın', ingredient: 'patates', vegetable: 'havuç', ingredients: ['2 orta boy haşlanmış patates', '2 yemek kaşığı rendelenmiş havuç', '2 yemek kaşığı rendelenmiş kaşar', '1 yumurta sarısı', '3 yemek kaşığı galeta unu'], steps: ['Fırını 200 °C\'ye ısıtın.', 'Patatesleri ezin; havuç, kaşar ve yumurta sarısıyla karıştırın.', 'Karışımdan parmak kalınlığında kroketler yapıp galeta ununa bulayın.', 'Kâğıt serili tepside 20 dakika, yarısında çevirerek altın rengi olana kadar pişirin.'], tips: ['Kızartmak yerine fırınlamak daha hafif bir seçenektir.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'ab18_10', title: 'Elmalı tarçınlı sütlaç', age: '18+', category: 'Tatlı', ingredient: 'pirinç', vegetable: 'elma', ingredients: ['2 yemek kaşığı pirinç', '1,5 su bardağı süt', 'Yarım su bardağı su', '1 küçük elma, rendelenmiş', '1 tutam tarçın'], steps: ['Pirinci suyla 15 dakika yumuşayana kadar pişirin.', 'Sütü ve rendelenmiş elmayı ekleyin.', 'Kısık ateşte sürekli karıştırarak 15–20 dakika koyulaşana kadar pişirin.', 'Kaselere paylaştırıp soğutun, servis ederken tarçın serpin.'], tips: ['Elma tatlılık sağlar; şeker eklemenize gerek yoktur.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'ab24_01', title: 'Kıymalı ıspanak yemeği', age: '24+', category: 'Et', ingredient: 'dana kıyma', vegetable: 'ıspanak', ingredients: ['60 g az yağlı dana kıyma', '2 su bardağı doğranmış ıspanak', '1 yemek kaşığı pirinç', '1 yemek kaşığı ince doğranmış soğan', '1 tatlı kaşığı domates salçası', 'Yarım su bardağı sıcak su', '1 tatlı kaşığı zeytinyağı'], steps: ['Zeytinyağında soğanı 2 dakika, ardından kıymayı ezerek 5 dakika kavurun.', 'Salçayı ekleyip 1 dakika çevirin.', 'Ispanak, pirinç ve sıcak suyu ekleyin; kapağı kapalı kısık ateşte 20 dakika pişirin.', 'Yoğurtla birlikte servis edin.'], tips: ['Ispanağı birkaç suda iyice yıkayarak toprağını giderin.'], storage: 'Buzdolabında 24 saat.'),
  BabyRecipe(id: 'ab24_02', title: 'Tavuk şiş (fırında)', age: '24+', category: 'Et', ingredient: 'tavuk göğsü', vegetable: 'kırmızı biber', ingredients: ['100 g tavuk göğsü, 2 cm küpler', '2 yemek kaşığı yoğurt', '1 tatlı kaşığı zeytinyağı', '1 tutam kekik ve tatlı toz biber', 'Yarım kırmızı biber, iri doğranmış'], steps: ['Tavuğu yoğurt, zeytinyağı ve baharatla karıştırıp en az 30 dakika buzdolabında bekletin.', 'Fırını 200 °C\'ye ısıtın.', 'Tavuk ve biberi tepsiye dizin (çocuklar için şiş çubuğu kullanmayın).', '18–20 dakika, tavuğun içi tamamen beyazlayana kadar pişirin.', 'Küçük parçalara bölerek bulgur pilavı ile servis edin.'], tips: ['Sivri şiş çubukları çocuk tabağına koymayın.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'ab24_03', title: 'Zeytinyağlı barbunya', age: '24+', category: 'Baklagil', ingredient: 'barbunya', vegetable: 'havuç', ingredients: ['Yarım su bardağı haşlanmış barbunya', '1 küçük havuç, küp doğranmış', '1 küçük patates, küp doğranmış', '1 yemek kaşığı ince doğranmış soğan', '1 küçük domates, rendelenmiş', '1 yemek kaşığı zeytinyağı', '1 su bardağı sıcak su'], steps: ['Zeytinyağında soğanı 3 dakika yumuşatın.', 'Havuç ve patatesi ekleyip 3 dakika çevirin, ardından domatesi ilave edin.', 'Barbunya ve sıcak suyu ekleyin; kısık ateşte 25 dakika pişirin.', 'Tencerede ılımaya bırakın, ılık veya oda sıcaklığında servis edin.'], tips: ['Zeytinyağlılar dinlenince daha lezzetli olur.'], storage: 'Buzdolabında 3 gün.'),
  BabyRecipe(id: 'ab24_04', title: 'Fırında sebzeli makarna', age: '24+', category: 'Makarna', ingredient: 'makarna', vegetable: 'brokoli', ingredients: ['Yarım su bardağı kısa makarna (burgu, kalem)', 'Yarım su bardağı küçük brokoli çiçekleri', '1 su bardağı süt', '1 yemek kaşığı tereyağı', '1 yemek kaşığı un', '3 yemek kaşığı rendelenmiş kaşar'], steps: ['Fırını 190 °C\'ye ısıtın. Makarnayı haşlayın, son 3 dakikada brokoliyi ekleyip birlikte süzün.', 'Tereyağında unu 1 dakika kavurun, sütü azar azar ekleyip koyulaşana kadar karıştırarak beşamel yapın.', 'Makarna ve brokoliyi beşamelle karıştırıp küçük fırın kabına alın.', 'Üzerine kaşar serpip 15 dakika, peynir kızarana kadar pişirin.', 'Biraz ılıtıp servis edin.'], tips: ['Beşamel topaklanırsa telle çırpın.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'ab24_05', title: 'Sebzeli mercimek köftesi parmakları', age: '24+', category: 'Baklagil', ingredient: 'yeşil mercimek', vegetable: 'havuç', ingredients: ['Yarım su bardağı haşlanmış yeşil mercimek', '3 yemek kaşığı rendelenmiş havuç', '3 yemek kaşığı yulaf ezmesi', '1 yumurta', '1 tutam kimyon', '1 yemek kaşığı ince kıyılmış maydanoz'], steps: ['Fırını 190 °C\'ye ısıtın.', 'Mercimeği çatalla kabaca ezin, diğer malzemeleri ekleyip yoğurun.', 'Karışımdan parmak şeklinde köfteler yapın.', 'Kâğıt serili tepside 20 dakika, yarısında çevirerek pişirin.', 'Yoğurtlu sos ile servis edin.'], tips: ['Çocuğun kendi kendine yemesini destekleyen parmak yiyeceklerdendir.'], storage: 'Buzdolabında 48 saat; dondurulabilir.'),
  BabyRecipe(id: 'ab24_06', title: 'Ev yapımı sebze çorbası (parçalı)', age: '24+', category: 'Çorba', ingredient: 'şehriye', vegetable: 'havuç', ingredients: ['1 küçük havuç', '1 küçük patates', 'Yarım kabak', '1 yemek kaşığı tel şehriye', '1 yemek kaşığı ince doğranmış soğan', '2,5 su bardağı sıcak su', '1 tatlı kaşığı tereyağı'], steps: ['Sebzeleri 1 cm küpler hâlinde doğrayın.', 'Tereyağında soğanı yumuşatıp sebzeleri ekleyin, 3 dakika çevirin.', 'Sıcak suyu ekleyip 15 dakika pişirin.', 'Şehriyeyi ekleyip 8 dakika daha pişirin.', 'Ilıtarak, parçalı şekilde servis edin.'], tips: ['Bu yaşta çorbayı blenderdan geçirmek yerine küçük parçalı vermek çiğnemeyi destekler.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'ab24_07', title: 'Peynirli omlet rulo', age: '24+', category: 'Kahvaltı', ingredient: 'yumurta', vegetable: 'domates', ingredients: ['2 yumurta', '2 yemek kaşığı süt', '2 yemek kaşığı lor veya beyaz peynir (tuzu alınmış)', '1 yemek kaşığı ince kıyılmış maydanoz', '1 çay kaşığı tereyağı'], steps: ['Yumurta ve sütü çırpın.', 'Geniş tavada tereyağını eritip yumurtayı ince bir tabaka hâlinde dökün.', 'Kapağı kapalı kısık ateşte üstü katılaşana kadar 3–4 dakika pişirin.', 'Peynir ve maydanozu serpip rulo şeklinde sarın, dilimleyerek domates dilimleriyle servis edin.'], tips: ['Beyaz peyniri 1 saat suda bekleterek tuzunu azaltın.'], storage: 'Hemen tüketin.'),
  BabyRecipe(id: 'ab24_08', title: 'Elmalı havuçlu muffin', age: '24+', category: 'Tatlı', ingredient: 'tam buğday unu', vegetable: 'elma', ingredients: ['1 su bardağı tam buğday unu', '1 çay kaşığı kabartma tozu', '1 olgun muz, ezilmiş', '1 küçük elma ve 1 küçük havuç, rendelenmiş', '1 yumurta', '3 yemek kaşığı zeytinyağı', '1 tatlı kaşığı tarçın'], steps: ['Fırını 180 °C\'ye ısıtın; muffin kalıbına kâğıt kapsüller yerleştirin.', 'Muz, yumurta ve zeytinyağını çırpın.', 'Elma ve havucu ekleyin; un, kabartma tozu ve tarçını eleyerek karıştırın.', 'Kalıpları üçte iki doldurup 20–22 dakika, kürdan temiz çıkana kadar pişirin.', 'Tel ızgarada soğutun.'], tips: ['Şeker yerine olgun muz tatlılık verir.'], storage: 'Hava almayan kapta 2 gün; dondurulabilir.'),
  BabyRecipe(id: 'ab24_09', title: 'Fırında balık köftesi', age: '24+', category: 'Balık', ingredient: 'levrek', vegetable: 'patates', ingredients: ['100 g kılçıksız levrek veya mezgit', '1 haşlanmış patates', '1 yemek kaşığı ince kıyılmış dereotu', '1 yumurta sarısı', '2 yemek kaşığı galeta unu'], steps: ['Fırını 200 °C\'ye ısıtın. Balığı 8 dakika buharda pişirip kılçık kontrolü yapın.', 'Balığı ve patatesi ezin; dereotu ve yumurta sarısını ekleyin.', 'Küçük köfteler şekillendirip galeta ununa bulayın.', 'Kâğıt serili tepside 15–18 dakika kızarana kadar pişirin.'], tips: ['Kılçık kontrolünü iki kez yapın.'], storage: 'Aynı gün tüketin.'),
  BabyRecipe(id: 'ab24_10', title: 'Yoğurtlu meyve dondurması (şekersiz)', age: '24+', category: 'Tatlı', ingredient: 'yoğurt', vegetable: 'çilek', ingredients: ['1 su bardağı süzme yoğurt', '1 su bardağı dondurulmuş çilek veya şeftali', '1 olgun muz'], steps: ['Tüm malzemeyi blenderda pürüzsüz olana kadar çekin.', 'Karışımı buzluk kalıplarına veya küçük kaplara paylaştırın.', 'En az 4 saat dondurucuda bekletin.', 'Servis etmeden 5 dakika önce çıkarın.'], tips: ['Sıcak havalarda diş çıkaran çocuklar için de rahatlatıcıdır.'], storage: 'Dondurucuda 1 ay.'),
  BabyRecipe(id: 'ab36_01', title: 'Ev yapımı tavuk nugget (fırında)', age: '36+', category: 'Et', ingredient: 'tavuk göğsü', vegetable: 'mısır gevreği', ingredients: ['200 g tavuk göğsü, parmak büyüklüğünde', '3 yemek kaşığı yoğurt', '1 su bardağı ezilmiş şekersiz mısır gevreği', '2 yemek kaşığı rendelenmiş kaşar', '1 tutam kekik ve tatlı toz biber'], steps: ['Tavuğu yoğurtla karıştırıp 30 dakika buzdolabında bekletin.', 'Fırını 200 °C\'ye ısıtın; mısır gevreği, kaşar ve baharatı karıştırın.', 'Tavuk parçalarını bu karışıma iyice bulayın, kâğıt serili tepsiye dizin.', '18–20 dakika, yarısında çevirerek içi tamamen pişene kadar pişirin.', 'Yoğurtlu dereotlu sosla servis edin.'], tips: ['Paneyi çocukla birlikte yapmak yemeğe ilgisini artırır.'], storage: 'Buzdolabında 48 saat; pişmeden dondurulabilir.'),
  BabyRecipe(id: 'ab36_02', title: 'Sebzeli pide', age: '36+', category: 'Fırın', ingredient: 'un', vegetable: 'kırmızı biber', ingredients: ['1 su bardağı un', 'Yarım çay kaşığı instant maya', 'Yarım su bardağı ılık su', '1 yemek kaşığı zeytinyağı', '3 yemek kaşığı rendelenmiş kaşar', '3 yemek kaşığı ince doğranmış kırmızı biber, mantar ve domates'], steps: ['Un, maya, su ve zeytinyağını yoğurup üzerini örterek 40 dakika mayalandırın.', 'Fırını 220 °C\'ye ısıtın; hamuru 2 parçaya bölüp kayık şeklinde açın.', 'Ortasına sebze ve kaşarı paylaştırıp kenarlarını kıvırın.', '12–15 dakika, kenarlar kızarana kadar pişirin.', 'Dilimleyerek servis edin.'], tips: ['Çocuğun kendi pidesini süslemesine izin verin.'], storage: 'Aynı gün tüketin.'),
  BabyRecipe(id: 'ab36_03', title: 'Kıymalı patates oturtma', age: '36+', category: 'Et', ingredient: 'dana kıyma', vegetable: 'patates', ingredients: ['100 g az yağlı dana kıyma', '2 orta boy patates, halka dilimlenmiş', '1 küçük soğan, ince doğranmış', '1 domates, rendelenmiş', '1 tatlı kaşığı domates salçası', '1 su bardağı sıcak su', '1 yemek kaşığı zeytinyağı'], steps: ['Fırını 190 °C\'ye ısıtın; patatesleri zeytinyağıyla harmanlayıp 15 dakika fırınlayın.', 'Soğanı ve kıymayı kavurun, salça ve domatesi ekleyip 5 dakika pişirin.', 'Patatesleri fırın kabına dizin, kıymalı harcı üzerine yayın.', 'Sıcak suyu ekleyip üzerini kapatarak 25 dakika pişirin.', 'Yoğurtla servis edin.'], tips: ['Az tuz kullanın; çocuklar için günlük tuz sınırı yetişkinlerden düşüktür.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'ab36_04', title: 'Zeytinyağlı pırasa', age: '36+', category: 'Sebze', ingredient: 'pırasa', vegetable: 'havuç', ingredients: ['2 pırasa (beyaz ve açık yeşil kısımları)', '1 havuç', '1 yemek kaşığı pirinç', '2 yemek kaşığı zeytinyağı', '1 su bardağı sıcak su', 'Birkaç damla limon suyu'], steps: ['Pırasaları ikiye yarıp aralarını bol suda yıkayın, 2 cm halkalar hâlinde doğrayın.', 'Zeytinyağında havucu 2 dakika, pırasayı 5 dakika çevirin.', 'Pirinci ve sıcak suyu ekleyip kapağı kapalı kısık ateşte 25 dakika pişirin.', 'Limon suyunu ekleyip tencerede soğumaya bırakın.'], tips: ['Çocuklara yeni sebzeleri tanıdık bir yiyecek yanında sunun.'], storage: 'Buzdolabında 3 gün.'),
  BabyRecipe(id: 'ab36_05', title: 'Fırında köfte ve sebze tepsisi', age: '36+', category: 'Et', ingredient: 'dana kıyma', vegetable: 'kabak', ingredients: ['150 g dana kıyma', '2 yemek kaşığı galeta unu', '1 yemek kaşığı rendelenmiş soğan', '1 tutam kimyon', '1 kabak, 1 havuç ve 1 patates, iri doğranmış', '1 yemek kaşığı zeytinyağı'], steps: ['Fırını 200 °C\'ye ısıtın.', 'Kıyma, galeta unu, soğan ve kimyonu yoğurup küçük köfteler yapın.', 'Sebzeleri zeytinyağıyla harmanlayıp tepsiye yayın, 15 dakika pişirin.', 'Köfteleri sebzelerin arasına yerleştirip 20 dakika daha, içleri pişene kadar pişirin.'], tips: ['Tek tepside pişen yemekler yoğun günlerde zaman kazandırır.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'ab36_06', title: 'Mercimek çorbası (aile usulü)', age: '36+', category: 'Çorba', ingredient: 'kırmızı mercimek', vegetable: 'havuç', ingredients: ['Yarım su bardağı kırmızı mercimek', '1 küçük havuç', '1 küçük patates', '1 küçük soğan', '1 tatlı kaşığı tereyağı', '4 su bardağı sıcak su', '1 tutam kimyon'], steps: ['Soğanı tereyağında 3 dakika yumuşatın.', 'Doğranmış havuç, patates ve yıkanmış mercimeği ekleyip 2 dakika çevirin.', 'Sıcak suyu ekleyip kısık ateşte 30 dakika pişirin.', 'Blenderdan geçirin, kimyon ekleyip 2 dakika daha kaynatın.', 'Limon ve kıtır ekmekle servis edin.'], tips: ['Ailece aynı yemeği yemek, çocuğun yeni tatları kabulünü kolaylaştırır.'], storage: 'Buzdolabında 3 gün; dondurulabilir.'),
  BabyRecipe(id: 'ab36_07', title: 'Yulaflı fıstık ezmeli toplar', age: '36+', category: 'Tatlı', ingredient: 'yulaf', vegetable: 'hurma', ingredients: ['1 su bardağı yulaf ezmesi', '3 yemek kaşığı şekersiz fıstık ezmesi', '4 adet çekirdeksiz hurma, ince kıyılmış', '1 yemek kaşığı kakao', '2 yemek kaşığı süt'], steps: ['Hurmaları 10 dakika sıcak suda bekletip süzün ve ezin.', 'Tüm malzemeyi karıştırın; gerekirse süt ekleyerek şekil alacak kıvama getirin.', 'Fındık büyüklüğünde toplar yapın.', 'En az 30 dakika buzdolabında bekletip servis edin.'], tips: ['Yer fıstığı alerjisi açısından ilk denemede az miktarda verin.', 'Topları küçük ve yumuşak tutun.'], storage: 'Buzdolabında kapalı kapta 5 gün.'),
  BabyRecipe(id: 'ab36_08', title: 'Sebzeli tavuk dürüm', age: '36+', category: 'Et', ingredient: 'lavaş', vegetable: 'marul', ingredients: ['1 tam buğday lavaş', '60 g ızgara veya haşlanmış tavuk, ince dilim', '2 yemek kaşığı rendelenmiş havuç', '1 yaprak marul, ince kıyılmış', '1 yemek kaşığı yoğurt', '1 yemek kaşığı rendelenmiş kaşar'], steps: ['Lavaşı tavada 30 saniye ısıtıp yumuşatın.', 'Ortasına yoğurt sürün; tavuk, havuç, marul ve kaşarı yerleştirin.', 'Alt kısmını katlayıp sıkıca sarın.', 'Ortadan ikiye veya 3 cm dilimlere keserek servis edin.'], tips: ['Okul/kreş beslenme çantası için uygundur.'], storage: 'Hemen tüketin.'),
  BabyRecipe(id: 'ab36_09', title: 'Fırında sebzeli kumpir', age: '36+', category: 'Fırın', ingredient: 'patates', vegetable: 'mısır', ingredients: ['1 büyük patates', '1 tatlı kaşığı tereyağı', '2 yemek kaşığı rendelenmiş kaşar', '2 yemek kaşığı haşlanmış mısır', '2 yemek kaşığı ince doğranmış salatalık ve havuç', '1 yemek kaşığı yoğurt'], steps: ['Fırını 200 °C\'ye ısıtın. Patatesi yıkayıp çatalla birkaç yerinden delin.', '50–60 dakika, şiş kolayca batana kadar fırında pişirin.', 'Ortadan yarıp içini tereyağı ve kaşarla çatalla karıştırın.', 'Mısır, sebzeler ve yoğurtla doldurup servis edin.'], tips: ['Mısır taneleri küçük çocuklarda boğulma riski taşıyabilir; çocuğunuzun çiğneme becerisine göre ezin.'], storage: 'Hemen tüketin.'),
  BabyRecipe(id: 'ab36_10', title: 'Ev yapımı granola bar', age: '36+', category: 'Kahvaltı', ingredient: 'yulaf', vegetable: 'kuru kayısı', ingredients: ['1,5 su bardağı yulaf ezmesi', '2 olgun muz, ezilmiş', '4 adet kuru kayısı, ince doğranmış', '2 yemek kaşığı tahin', '1 tatlı kaşığı tarçın'], steps: ['Fırını 180 °C\'ye ısıtın; 20×20 cm kabı pişirme kâğıdıyla kaplayın.', 'Tüm malzemeyi iyice karıştırın.', 'Karışımı kaba bastırarak düzgünce yayın.', '20–25 dakika, kenarları kızarana kadar pişirin.', 'Tamamen soğuduktan sonra bar şeklinde kesin.'], tips: ['Bütün kuruyemiş yerine ince doğranmış kuru meyve kullanılmıştır; 4 yaş altında bütün kuruyemiş vermeyin.'], storage: 'Hava almayan kapta 4 gün.'),
];
